"""Curated physical decisions from inspected plots, timing, pixels and aliases."""
from pathlib import Path
import csv,json,hashlib
B=Path(__file__).resolve().parent
Q=list(csv.DictReader((B/'queue.csv').open(newline='',encoding='utf8')))
common='Catalogues: shared-catalogues/TARGET-STATUS.csv and target-evidence.json. Per-target VSX/ASAS-SN/Kostov gates unavailable; primary-table nonmatches are not novelty clearance.'
D={
'N001':dict(v='PLAUSIBLE',n='UNKNOWN',p='',e='1959.089',d='40',why='S24 and S50 contain nearly identical ~40 ppt flat eclipses at BTJD 1959.089 and 2685.012; a shallower S23 1936.757 dip may be another kind but does not fix the clock. S24 TESSCut loss is near the target (0.15 pixel), with 38.9 ppt in a 5x5 aperture; capable neighbors are projected in actual WCS.',alias='The deep-event separation is 725.923 d. Conditional k=21 gives 34.568 d near Gaia 34.579 d, but k=19 and 23 also have no additional tested occasion in cached sectors. k=20 and 22 predict strong observed flat windows. The deeper-event cycle count is therefore not measured.',geom='Gaia SB1 P=34.57876 d, e=0.381; a shorter/shallow secondary phase is physically possible but not established. Two deep events and a possible other-kind event do not meet the repeating-clock criterion.',limit='Integer aliases untested; second-sector pixel localization and independent pipeline remain limited.',next='Acquire a third primary eclipse or archival non-QLP event at a discriminating cycle.'),
'N002':dict(v='REFUTED',n='UNKNOWN',p='',e='',d='',why='QLP has many real-looking ~27–29 ppt dips in S18/S58/S85, repeating near 4.536 d. S18 and S58 independent TESSCut difference peaks coincide with Gaia DR3 510176423251346432 (G=11.98), ~3 pixels below the queued target in both actual WCS frames; the source has ample approximate flux to produce the blended loss.',alias='The neighbor recurrence is not an eclipse period for TIC 370126865. The ~4.536 d dip train also differs sharply from the target Gaia SB1 21.655 d.',geom='Gaia orbit of the queued star is not associated by the pixel data with the selected dip.',limit='Refutes attribution of selected signal to queued target, not its possible independent binarity. Nondetections of target eclipses are not claimed.',next='If scientifically useful, review the G11.98 neighbor as a separate target.'),
'N003':dict(v='REFUTED',n='UNKNOWN',p='',e='',d='',why='S39 2371.49 toggles abruptly between flat ~0.95 and 1.04 states across gaps, while 2389.10 is a sector-end recovery after a multi-day structured decline. S62 2999.64 is a smooth decline before a downlink gap with shifted post-gap baseline. Full raw sector panels show strong sector-wide drifts/steps; none of these flagged windows is an isolated eclipse.',alias='No defensible same-kind times or period follow from the flagged windows.',geom='Gaia SB1 46.769 d is only a selection orbit here; the apparent raw flags do not identify conjunctions.',limit='Selected detector windows refuted as eclipses; this does not prove the star has no binary eclipses elsewhere.',next='Use a stable independent light curve if pursuing this variable.'),
'N004':dict(v='PROBABLE',n='UNKNOWN',p='20.450',e='2510.814',d='130',why='Deep, rounded raw SAP eclipses in S44 2510.814, S45 2531.264 and S72 3267.463 repeat at ~20.45 d; other shallower structures may be opposite-kind events. Independent S44 TESSCut loss is near target (0.24 pixel) with 110 ppt in 5x5 versus 124 ppt QLP SAP. Actual WCS includes a G10.13 neighbor displaced ~2.7 pixels; target-favored difference image and deep loss disfavor it.',alias='S44→S45 is 20.44984 d and S45→S72 is 736.199 d (~36×20.45). S72 fit width and ingress are nonidentifiable, so its small formal center error is not used. Actual q0 S44 at BTJD2521.039 fully covers P/2 with −5.8 ppt local depth versus ~130 ppt primary; S44 2517.630 fully covers P/3 with −6.3 ppt; S44 2505.701 covers P/4 with only 8.8 ppt amid smooth variation. Local coverage/gaps, baseline counts, MAD and visual panels are in submultiple-tests.json/png. These reject the neighboring short same-kind clocks; rounded P≈20.450 d is adopted.',geom='Gaia SB2 e=0.343 and large RV amplitudes can permit deep eclipses, but Gaia P=20.46508±0.00355 d is ~4.3 nominal sigma from the photometric ~20.450 d. Source-specific covariance calculation puts S44 0.0678 phase early of nearest Gaia A conjunction (~3.95 linear sigma). Gaia-orbit association/geometry therefore remains unresolved.',limit='Gaia conjunction and period tension; S72 nonidentifiable timing; crowded aperture depth.',next='Independent precise event centers and Gaia-orbit reconciliation.'),
'N005':dict(v='PROBABLE',n='UNKNOWN',p='',e='2042.2',d='65',why='Long flat-bottomed raw eclipses recur in S27 2042.16, S39 2386.3 and S65 3075.2. S12 1633.24 and S13 1676.40 show similar shallower events ~43.16 d apart, plausibly another eclipse kind amid large trends. S39 raw TESSCut 5x5 reproduces a 45.7 ppt deficit near target (0.33 pixel); QLP corrected flux suppresses it, which does not negate the raw spatial signal.',alias='Deep S27→S65 separation 1033.03 d gives conditional k=24 P≈43.043 d, with S39 near cycle 8. The deep-event cycle labels 0/8/24 under that conditional clock do not exclude alternative integer counts (e.g. 7 or 9 cycles S27→S39, or their shorter submultiples). S39 fit is singular/bound-hitting, and shallow S12/S13 centers are trend-limited. Orbital period is left unadopted.',geom='Gaia SB1 e=0.067 and P=43.0472 d; source-specific covariance places deep S27 near B conjunction (−0.0188 phase, −1.59 linear sigma), supportive but not cycle uniqueness. Repeated flat cores favor occultation over smooth tidal modulation.',limit='Integer aliases and broad-fit timing unresolved; raw trends/gaps vary depths. Newly available S93 cutout has near-zero target flux (~0.65 units), invalid for a null.',next='Get a sensitive intermediate same-kind eclipse; re-extract a usable S93 product if available.'),
'N006':dict(v='PLAUSIBLE',n='KNOWN',p='',e='1891.863',d='21',why='S21 1891.863 and S47 2603.626 are matching ~2.1% narrow raw dips. QLP and historical SPOC/TESS-SPOC reductions agree; S47 TESSCut difference is shifted away from the nearby G11.70 neighbor and close to target. Prior Fable appointment report measured both events, a target-centered pixel fit, and physical M-dwarf geometry; the system is previously listed as TOI-5746/EB.',alias='Separation 711.763 d gives conditional N=29 P=24.5436 d, near Gaia SB1 24.5686 d. Actual q0 data have no additional in-sector primary occasion for N=28,29,30. Older report rejects 28/30 by Gaia-period prior (>50 sigma), not by observed intervening primary eclipses. Under this campaign’s photometric cycle-uniqueness convention the orbital period remains unadopted.',geom='Gaia SB1 e=0.112 and historical source-specific geometry support a grazing M-dwarf eclipse; this is not a refutation of that earlier confirmed EB or its conditional Gaia-supported ephemeris.',limit='Only two observed primary occasions and neighboring integer aliases untested photometrically. Historical report is reused with provenance, not silently imported as a new verdict.',next='Third primary eclipse at a cycle distinguishing N=28/29/30; prior report [local-path-redacted] 5.1/made/appointments/vet318209162/REPORT.md.'),
'N007':dict(v='PLAUSIBLE',n='UNKNOWN',p='',e='2712.682',d='18',why='S51 2712.682 and S79 3454.354 show matching ~18 ppt flat raw dips. S79 TESSCut loss is near target (0.076 pixel) and 5x5 depth 16.7 ppt; the nearest potentially capable listed Gaia neighbor has G12.97 and only ~0.05 target G flux.',alias='Separation 741.672 d gives conditional k=19 P=39.035 d, near Gaia SB1 39.0288 d, but k=16–20 have no extra fully tested primary occasion. k=21–23 predict actual flat windows. Two-event period is therefore conditional.',geom='Gaia SB1 e=0.070 and ~39 d orbit permit the observed short flat event; target attribution is favored.',limit='No third same-kind occasion or independent period; second-sector pixel test is limited.',next='Observe a third primary at a discriminating alias epoch.'),
'N008':dict(v='PROBABLE',n='UNKNOWN',p='',e='2046.070',d='10',why='S27 2046.07 and S67 3131.71 have matching ~10–13 ppt rounded raw dips. Newly available S105 target-centered raw TESSCut shows a third ~9.5 ppt dip near 4217.35; its 3x3 flux is positive across all 9290 quality-zero cadences and the difference peak is the target pixel (6,6), with valid core/pre/post counts 259/216/201. S67 independent cutout also centers near target. These are three observing occasions.',alias='The two long gaps are each ~1085.64 d. Any integer k cycles per gap reproduces all three times, so equal spacing does not select an orbital period. k=19 or 20 would imply ~57.14 or 54.28 d, both discrepant from Gaia SB2 55.5332 d. A long-period event train or bycatch relative to Gaia is possible.',geom='Gaia SB2 e=0.115 does not yet explain a secure eclipse clock at these times; target association and repeating dip are stronger than the Gaia-orbit association.',limit='Orbital cycle count and Gaia association unresolved; S105 is a raw TESSCut reduction of new photons, not a QLP light curve.',next='Targeted fourth occasion or intervening eclipse to resolve integer clock and Gaia relationship.'),
'N009':dict(v='REFUTED',n='UNKNOWN',p='',e='',d='',why='Seventy-five short QLP dip windows form a coherent ~2.068 d train, but S19 and S73 difference images locate the loss near Gaia DR3 2292102073101008000 (G12.89), ~3 pixels from queued TIC235985439. S19 local pixel drop is ~17.2% at neighbor versus 0.006% at target; S73 ~16.3% versus 0.63% at target. Distinct WCS orientations support the same off-target source.',alias='The short train belongs to neighbor vicinity; no target eclipse period is measured. It is unrelated to the queued target Gaia SB1 P29.577 d.',geom='Pixel source attribution refutes the target-selected claim, regardless of repeat strength.',limit='The neighbor itself may be a real EB; no verdict on target independent variability.',next='Review G12.89 neighbor separately if desired.'),
'N010':dict(v='PROBABLE',n='UNKNOWN',p='56.823',e='1635.9',d='26',why='Deep S12 1635.896 and S100 4079.290 eclipses repeat over ~43 Gaia cycles. Shallower S11 1607.486, S65 3084.901, S99 4050.924 and S101 4107.660 events alternate at ~half the orbital interval, consistent with two eclipse kinds. S12 and S100 TESSCut differences peak near target; target-center pixel drops 2.51/2.84%, while capable G12.04 neighbor-center drops 1.30/1.17%, favoring target spillover to neighbor but not uniquely deblending their PSFs.',alias='S12→S100 deep interval /43 gives conditional 56.8231 d. Shallower S11→S101 has k=44 favored by S65/S99 timing over k=43/45; slope-limited shallow centers differ by ~0.04–0.09 d. Reported 56.823 d is rounded same-kind clock, not a precision fit.',geom='Gaia SB1 e≈0.002 and P=56.8227 d. Source-specific covariance puts S12 −0.0028 phase (−0.53 linear sigma) from Gaia B conjunction. Orbital geometry is supportive, but close-source ambiguity remains.',limit='Capable G12.04 neighbor not fully PRF-deblended; corrected columns suppress long raw events. S102 new cutout has no finite target-flux cadences and cannot yield a null.',next='PSF deblending and joint two-kind fit for secure ownership and depth.')}
for row in Q:
    sid=row['sample_id'];x=D[sid];tic=row['tic'];o=B/tic
    source=B.parent/'source-packets'/tic/'sources.json'
    assert source.exists()
    prior=''
    if sid=='N006':
        p=Path('[local-path-redacted] 5.1/made/appointments/vet318209162/REPORT.md')
        prior=f' Historical report SHA256 {hashlib.sha256(p.read_bytes()).hexdigest()}.'
    extras=[]
    if sid in ('N001','N006','N007','N008'):extras.append('Sparse pair alias diagnostics: `../alias-tests.json`.')
    if sid=='N004':extras.append('P/2–P/4 raw null checks: `submultiple-tests.json` and `submultiple-tests.png`. MAST label sector1751 has no validated light curve and was not used as science coverage.')
    if sid=='N008':extras.append('S105 new cutout hash, actual coverage and plot: `s105-check.json`, `s105-event.png`.')
    if sid in ('N005','N010'):extras.append('New sector validity checks: `../latest-check.json`.')
    if sid in ('N001','N004','N005','N006','N007','N008','N010'):extras.append('Source-specific Gaia conjunction diagnostic: `../gaia-geometry.json`.')
    report=f"# {sid} TIC {tic}: {x['v']}\n\nSelected stratum: {row['sample_stratum']}; original priority rank {row['priority_rank']}. Bounded full review complete. Novelty: {x['n']}.\n\n## Raw signal and source\n\n{x['why']}\n\n## Timing and physics\n\n{x['alias']} {x['geom']}\n\n## Limits and next check\n\n{x['limit']} Next: {x['next']}\n\n## Reproducibility\n\nRaw q0 SAP sectors, detector windows and coverage are in `screen.json`, `all-sectors.png`, `ranked-windows.png`; local provisional fits in `fitted-windows.json` and `fitted-windows.png`. The verified original paths and SHA256 hashes are in `{source}`. Pixel checks and source hashes are in `../helper-audit.md` and helper-prefixed artifacts. The sector availability receipt is `../../root-availability.json`. {' '.join(extras)} {common}{prior}\n"
    (o/'REPORT.md').write_text(report,encoding='utf8')
fields=['sample_id','tic','sample_stratum','physical_verdict','full_review_completion','novelty_status','period_days','period_error_days','primary_epoch_btjd','depth_ppt','limitations','next_check','report']
with (B/'RESULTS.csv').open('w',newline='',encoding='utf8') as f:
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
    for r in Q:
        x=D[r['sample_id']];w.writerow({'sample_id':r['sample_id'],'tic':r['tic'],'sample_stratum':r['sample_stratum'],'physical_verdict':x['v'],'full_review_completion':'COMPLETE','novelty_status':x['n'],'period_days':x['p'],'period_error_days':'','primary_epoch_btjd':x['e'],'depth_ppt':x['d'],'limitations':x['limit'],'next_check':x['next'],'report':str(B/r['tic']/'REPORT.md')})
print('wrote',len(Q),'reports and RESULTS.csv')

